{
	struct device *dev = &pdev->dev;
	struct example_button *b;
	struct resource *res;
	int ret;

	b = kzalloc(sizeof(*b), GFP_KERNEL);
	if (!b)
		return -ENOMEM;
	b->dev = dev;

	res = platform_get_resource(pdev, IORESOURCE_MEM, 0);
	if (!res) {
		ret = -ENODEV;
		goto err_free;
	}
	b->regs = ioremap(res->start, resource_size(res));
	if (!b->regs) {
		ret = -ENOMEM;
		goto err_free;
	}

