				   DRIVER_NAME, b);
	if (ret)
		goto err_iomap;

	dev_info(dev, "%s: probed irq=%d\n", DRIVER_NAME, b->irq);
	return 0;

err_iomap:
	iounmap(b->regs);
err_free:
	kfree(b);
	return ret;
}

