	p->task = kthread_run(example_poll_thread, p, "%s-poll", DRIVER_NAME);
	if (IS_ERR(p->task)) {
		ret = PTR_ERR(p->task);
		goto err_iomap;
	}

	dev_info(dev, "%s: probed\n", DRIVER_NAME);
	return 0;

err_iomap:
	iounmap(p->regs);
err_free:
	kfree(p);
	return ret;
}

static int example_poll_remove(struct platform_device *pdev)
{
	struct example_poll *p = platform_get_drvdata(pdev);

	kthread_stop(p->task);
	iounmap(p->regs);
	kfree(p);
	return 0;
}

